export function connectChat(url: string, token: string, lastId: string) {
  const ws = new WebSocket(url) // cookies ride the handshake; no Authorization header
  let delayMs = 1000
  let beat: ReturnType<typeof setInterval> | undefined
  ws.addEventListener("open", () => {
    ws.send(JSON.stringify({ type: "auth", token, lastId })) // first-message auth
    delayMs = 1000
    beat = setInterval(() => ws.send(JSON.stringify({ type: "ping" })), 25_000)
  })
  ws.addEventListener("close", () => {
    clearInterval(beat)
    const jitter = Math.random() * 400
    setTimeout(() => connectChat(url, token, lastId), delayMs + jitter)
    delayMs = Math.min(delayMs * 2, 30_000) // cap; reset after a stable open
  })
  return ws
}

