async function onToggleDone(id: string) {
  const key = ["orders", userId] // key by user or permissions go stale
  const snapshot = queryClient.getQueryData(key)
  queryClient.setQueryData(key, optimisticToggle(snapshot, id)) // guess
  try {
    await $fetch(`/api/orders/${id}`, { method: "PATCH", body: { done: true } })
  } catch (err) {
    queryClient.setQueryData(key, snapshot) // rollback
    toast.error("Could not update — still not marked done")
    throw err
  }
}
// payments stay pessimistic: await POST /pay, then invalidate — no guess

