export async function loadMe() {
  const res = await fetch("https://api.internal.example/me", {
    method: "GET",
    credentials: "include", // send the first-party cookie
    headers: { "X-Requested-With": "app" }, // custom header → preflight
  })
  if (!res.ok) throw new Error(String(res.status))
  return res.json()
}
// Network: OPTIONS, then GET. Allow-Origin must be exact, not *
// Allow-Credentials: true. CORS does not stop curl or a mobile WebView.

