export async function searchOrders(q: string, routeSignal: AbortSignal) {
  const signal = AbortSignal.any([routeSignal, AbortSignal.timeout(8_000)])
  try {
    return await $fetch("/api/orders", { query: { q }, signal })
  } catch (err) {
    const name = (err as DOMException).name
    if (name === "AbortError" || name === "TimeoutError") return null
    throw err
  }
}
// JavaScript 1.2.7 shows watch() aborting the previous typeahead.
// Do not abort POST /pay on unmount — keep Idempotency-Key instead.

